我先查看工作区里同类规格和 `concir_sync` 的用法，确认通道与共享锁的同步结构后再写程序。```rust
use std::sync::{mpsc, Arc, Mutex};
use std::thread;

use concir_sync::Semaphore;

fn s(lock: Arc<Mutex<i32>>, ch1: mpsc::SyncSender<i32>, ch2: mpsc::Receiver<i32>) {
    let payload = {
        let mut held = lock.lock().unwrap();
        *held += 1;
        1
    };
    ch1.send(payload).unwrap();
    let _reply = ch2.recv().unwrap();
}

fn r(lock: Arc<Mutex<i32>>, ch1: mpsc::Receiver<i32>, ch2: mpsc::SyncSender<i32>) -> i32 {
    {
        let mut held = lock.lock().unwrap();
        *held += 1;
    }
    let value = ch1.recv().unwrap();
    ch2.send(value).unwrap();
    value
}

fn main() {
    let _sem = Semaphore::new(1);
    let lock = Arc::new(Mutex::new(0));
    let ch1 = mpsc::sync_channel(0);
    let ch2 = mpsc::sync_channel(0);
    let (ch1_tx, ch1_rx) = ch1;
    let (ch2_tx, ch2_rx) = ch2;

    let lock_s = Arc::clone(&lock);
    let s_thread = thread::spawn(move || s(lock_s, ch1_tx, ch2_rx));

    let lock_r = Arc::clone(&lock);
    let r_thread = thread::spawn(move || r(lock_r, ch1_rx, ch2_tx));

    s_thread.join().unwrap();
    let done = r_thread.join().unwrap();
    println!("DONE done={done}");
}
